  id,
  autosave,
  collection,
  docWithLocales,
  draft,
  global,
  operation,
  payload,
  req,
  returning,
  select,
  unpublish,
}: Args<TData>): Promise<JsonObject | null> {
  let result: JsonObject | undefined
  let createdNewVersion = false
  const now = new Date().toISOString()
  const versionData: {
